/// When MolBioCraft rebuilt the alignment, tree and contig-assembly samples (US-01M6TDSV): the
/// `created_at` / `updated_at` of every document here and the time of its history entries. No
/// sample carries another program's document dates or its `Created` / `Modified` fields.
const REBUILT_AT: &str = "2026-11-08T09:00:00Z";
const REBUILT_STAMP: &str = "2026-11-08 09:00";

/// The MolBioCraft MSA preset and residue cap the aligned samples were built with, as their
/// `Alignment preset` and `Alignment max residues` metadata name them. Aligning the members'
/// fetched records with these (and, for a translation alignment, the frame and genetic code its
/// metadata names) gives the stored rows exactly (src/__tests__/sampleAlignmentProvenance.test.ts).
const SAMPLE_MSA_PRESET: &str = "MAFFT (FFT-NS-i / L-INS-i)";
const SAMPLE_MSA_MAX_RESIDUES: usize = 6000;

/// One of the aligned samples: MolBioCraft's MSA of its members (`members` holds the rows), with
/// the majority consensus as its sequence. With `translation_frame`, the rows are MolBioCraft's
/// Translation Alignment instead (Align > Translation Alignment: the members translated in that
/// frame with `genetic_code`, the proteins aligned with the preset, and the codons threaded back
/// onto them), so a coding set keeps every codon whole. `pairwise_identity_pct` and `identical_sites_pct` are
/// MolBioCraft's statistics on the rows, which scripts/outside-data/ref_align.py reproduces
/// independently (test-data/reference/align.json).
#[allow(clippy::too_many_arguments)]
fn rebuilt_alignment_document(
    id: &str,
    name: &str,
    accession: &str,
    description: &str,
    molecule_type: MoleculeType,
    consensus: &str,
    members: Vec<AlignmentMemberSequence>,
    pairwise_identity_pct: f64,
    identical_sites_pct: f64,
    genetic_code: &str,
    translation_frame: Option<u8>,
) -> SequenceDocument {
    let width = consensus.len();
    let method = if translation_frame.is_some() { "MolBioCraft Translation Alignment" } else { "MolBioCraft MSA" };
    let how = match translation_frame {
        Some(frame) => format!(
            "translated in frame {frame} with the {genetic_code} code, the proteins aligned with MolBioCraft's {SAMPLE_MSA_PRESET} preset and the codons threaded back"
        ),
        None => format!("aligned with MolBioCraft's {SAMPLE_MSA_PRESET} preset"),
    };
    let n = members.len();
    let lengths: Vec<usize> = members.iter().map(|m| m.sequence.bytes().filter(|&b| b != b'-').count()).collect();
    let residues: usize = lengths.iter().sum();
    let mean_coverage = ((residues as f64 / width.max(1) as f64) * 10.0).round() / 10.0;
    let nucleotide = molecule_type != MoleculeType::Protein;
    SequenceDocument {
        id: id.to_string(),
        name: name.to_string(),
        accession: accession.to_string(),
        description: description.to_string(),
        molecule_type,
        topology: Topology::Linear,
        sequence: consensus.to_string(),
        features: Vec::new(),
        primers: Vec::new(),
        history: vec![HistoryTreeNode {
            id: format!("hist-{id}"),
            timestamp: REBUILT_STAMP.to_string(),
            operation: format!("{method} ({SAMPLE_MSA_PRESET})"),
            description: format!("The {n} members' NCBI records, {how} ({} columns)", molbiocraft_core::format_thousands(width)),
            parent_ids: Vec::new(),
            length_bp: width,
            topology: Topology::Linear,
            history_color: Some("#2563eb".to_string()),
            inserted_range: None,
        }],
        chromatogram: None,
        alignment_meta: Some(DocumentAlignmentMeta {
            sequence_count: Some(n),
            pairwise_identity_pct: Some(pairwise_identity_pct),
            identical_sites_pct: Some(identical_sites_pct),
            genetic_code_label: Some(genetic_code.to_string()),
            mean_coverage_x: Some(mean_coverage),
            tree_builder: None,
            is_aligned: Some(true),
            sequences: Some(members),
        }),
        document_kind: Some("alignment".to_string()),
        doc_metadata: Some(make_meta(&[
            ("Sequence Length", serde_json::json!(molbiocraft_core::format_thousands(width))),
            ("# Sequences", serde_json::json!(n)),
            ("% Pairwise Identity", serde_json::json!(format!("{pairwise_identity_pct:.1}%"))),
            ("% Identical Sites", serde_json::json!(format!("{identical_sites_pct:.1}%"))),
            ("Genetic Code", serde_json::json!(genetic_code)),
            ("Alignment method", serde_json::json!(method)),
            ("Translation frame", translation_frame.map(|f| serde_json::json!(f)).unwrap_or(serde_json::Value::Null)),
            ("Alignment preset", serde_json::json!(SAMPLE_MSA_PRESET)),
            ("Alignment max residues", serde_json::json!(SAMPLE_MSA_MAX_RESIDUES)),
            (
                "# Nucleotides",
                serde_json::json!(if nucleotide { molbiocraft_core::format_thousands(residues) } else { String::new() }),
            ),
            ("Max Sequence Length", serde_json::json!(molbiocraft_core::format_thousands(lengths.iter().copied().max().unwrap_or(0)))),
            ("Min Sequence Length", serde_json::json!(molbiocraft_core::format_thousands(lengths.iter().copied().min().unwrap_or(0)))),
            ("Mean Coverage", serde_json::json!(format!("{mean_coverage:.1}"))),
        ])
        .into_iter()
        .filter(|(_, v)| !v.is_null())
        .collect()),
        created_at: REBUILT_AT.to_string(),
        updated_at: REBUILT_AT.to_string(),
        folder: "Alignments".to_string(),
    }
}

/// One of the unaligned samples: its members are their NCBI records, ungapped, for the user to
/// align.
fn unaligned_set_document(
    id: &str,
    name: &str,
    accession: &str,
    description: &str,
    molecule_type: MoleculeType,
    feature: SequenceFeature,
    members: Vec<AlignmentMemberSequence>,
) -> SequenceDocument {
    let n = members.len();
    let lengths: Vec<usize> = members.iter().map(|m| m.sequence.len()).collect();
    let residues: usize = lengths.iter().sum();
    let nucleotide = molecule_type != MoleculeType::Protein;
    SequenceDocument {
        id: id.to_string(),
        name: name.to_string(),
        accession: accession.to_string(),
        description: description.to_string(),
        molecule_type,
        topology: Topology::Linear,
        sequence: members.first().map(|m| m.sequence.clone()).unwrap_or_default(),
        features: vec![feature],
        primers: Vec::new(),
        history: Vec::new(),
        chromatogram: None,
        alignment_meta: Some(DocumentAlignmentMeta {
            sequence_count: Some(n),
            pairwise_identity_pct: None,
            identical_sites_pct: None,
            genetic_code_label: Some("-".to_string()),
            mean_coverage_x: None,
            tree_builder: None,
            is_aligned: Some(false),
            sequences: Some(members),
        }),
        document_kind: Some("alignment".to_string()),
        doc_metadata: Some(make_meta(&[
            ("Sequence Length", serde_json::json!("-")),
            ("# Sequences", serde_json::json!(n)),
            ("% Pairwise Identity", serde_json::json!("-")),
            ("% Identical Sites", serde_json::json!("-")),
            ("Genetic Code", serde_json::json!("-")),
            (
                "# Nucleotides",
                serde_json::json!(if nucleotide { molbiocraft_core::format_thousands(residues) } else { String::new() }),
            ),
            ("Max Sequence Length", serde_json::json!(molbiocraft_core::format_thousands(lengths.iter().copied().max().unwrap_or(0)))),
            ("Min Sequence Length", serde_json::json!(molbiocraft_core::format_thousands(lengths.iter().copied().min().unwrap_or(0)))),
        ])),
        created_at: REBUILT_AT.to_string(),
        updated_at: REBUILT_AT.to_string(),
        folder: "Alignments".to_string(),
    }
}

fn region_feature(id: &str, name: &str, feature_type: &str, start: usize, end: usize, color: &str, notes: &str) -> SequenceFeature {
    SequenceFeature {
        id: id.to_string(),
        name: name.to_string(),
        feature_type: feature_type.to_string(),
        start,
        end,
        strand: 1,
        color: color.to_string(),
        notes: Some(notes.to_string()),
        qualifiers: None,
        segments: None,
        cleavage_site: None,
    }
}

/// The sample alignments, then the trees MolBioCraft builds from the aligned ones.
pub fn get_alignment_sample_documents() -> Vec<SequenceDocument> {
    let mut docs = vec![
        // 1. COXII CDS (50 vertebrate mitochondrial COX2 coding sequences, codon-aligned)
        rebuilt_alignment_document(
            "doc-aln-coxii-cds",
            "COXII CDS",
            "ALN_COXII_50",
            "MolBioCraft translation alignment of 50 vertebrate cytochrome c oxidase subunit II coding sequences",
            MoleculeType::DNA,
            COXII_CDS_CONSENSUS,
            coxii_cds_members(),
            72.2,
            33.2,
            "Vertebrate Mitochondrial",
            Some(1),
        ),
        // 2. HIV env (20 unaligned HIV-1 envelope genes)
        unaligned_set_document(
            "doc-aln-hiv-env",
            "HIV env",
            "ALN_HIV_ENV_20",
            "20 HIV envelope genes",
            MoleculeType::RNA,
            region_feature("hiv-env-cds", "env CDS", "CDS", 1, 2580, "#8b5cf6", "HIV-1 subtype C envelope surface glycoprotein gp160"),
            hiv_env_members(),
        ),
        // 3. Ig variable region (5 unaligned human heavy-chain variable regions)
        unaligned_set_document(
            "doc-aln-ig-variable",
            "Ig variable region",
            "ALN_IG_VAR_5",
            "5 immunoglobulin heavy chain variable regions",
            MoleculeType::RNA,
            region_feature("ig-vh-cds", "immunoglobulin heavy chain variable region CDS", "CDS", 1, 264, "#8b5cf6", "Homo sapiens Ig heavy chain variable domain"),
            ig_variable_members(),
        ),
        // 4. LysR family (7 unaligned LysR-type transcriptional regulators)
        unaligned_set_document(
            "doc-aln-lysr-family",
            "LysR family",
            "ALN_LYSR_7",
            "7 LysR protein sequences",
            MoleculeType::Protein,
            region_feature("lysr-hth", "LysR substrate-binding domain", "Region", 1, 306, "#06b6d4", "Bacterial LysR-type HTH transcriptional regulator"),
            lysr_family_members(),
        ),
        // 5. Pairwise protein (actinidin 2ACT chain A and papain 1BP4 chain A)
        rebuilt_alignment_document(
            "doc-aln-pairwise-protein",
            "Pairwise protein",
            "ALN_2ACT_1BP4",
            "MolBioCraft alignment of the cysteine peptidases actinidin (kiwifruit) and papain (papaya)",
            MoleculeType::Protein,
            PAIRWISE_PROTEIN_CONSENSUS,
            pairwise_protein_members(),
            46.1,
            46.6,
            "-",
            None,
        ),
        // 6. Three Kingdoms (35 alanyl-tRNA synthetases from the three domains of life)
        rebuilt_alignment_document(
            "doc-aln-three-kingdoms",
            "Three Kingdoms",
            "ALN_3KINGDOMS_35",
            "MolBioCraft multiple alignment of alanyl-tRNA synthetase from organisms in 3 kingdoms",
            MoleculeType::Protein,
            THREE_KINGDOMS_CONSENSUS,
            three_kingdoms_members(),
            36.1,
            6.3,
            "-",
            None,
        ),
        // 7. Transcript variants (4 MAPK10 transcript variants)
        rebuilt_alignment_document(
            "doc-aln-transcript-variants",
            "Transcript variants",
            "ALN_MAPK10_4",
            "MolBioCraft multiple alignment of 4 transcript variants of the MAPK10 gene",
            MoleculeType::RNA,
            TRANSCRIPT_VARIANTS_CONSENSUS,
            transcript_variants_members(),
            93.3,
            87.1,
            "-",
            None,
        ),
    ];
    let trees = reference_tree_documents(&docs);
    docs.extend(trees);
    docs
}

