/// Tip, node and height counts read straight off a stored Newick string, so the Info panel can
/// never claim a shape the stored topology does not have.
struct NewickTreeStats {
    tips: usize,
    nodes: usize,
    height: f64,
}

enum NewickToken {
    Open,
    Close,
    Comma,
    /// A tip name, or a support label written after a closing paren.
    Label,
    Length(f64),
}

fn tokenize_newick(newick: &str) -> Vec<NewickToken> {
    let bytes = newick.as_bytes();
    let mut tokens = Vec::new();
    let mut i = 0usize;
    while i < bytes.len() {
        match bytes[i] {
            b'(' => {
                tokens.push(NewickToken::Open);
                i += 1;
            }
            b')' => {
                tokens.push(NewickToken::Close);
                i += 1;
            }
            b',' => {
                tokens.push(NewickToken::Comma);
                i += 1;
            }
            b';' => break,
            b'\'' => {
                let start = i + 1;
                let mut j = start;
                while j < bytes.len() {
                    if bytes[j] == b'\'' {
                        // A doubled quote is an escaped quote inside the label.
                        if j + 1 < bytes.len() && bytes[j + 1] == b'\'' {
                            j += 2;
                            continue;
                        }
                        break;
                    }
                    j += 1;
                }
                let _ = start;
                tokens.push(NewickToken::Label);
                i = j + 1;
            }
            b':' => {
                let start = i + 1;
                let mut j = start;
                while j < bytes.len()
                    && (bytes[j].is_ascii_digit()
                        || matches!(bytes[j], b'.' | b'-' | b'+' | b'e' | b'E'))
                {
                    j += 1;
                }
                tokens.push(NewickToken::Length(newick[start..j].parse::<f64>().unwrap_or(0.0)));
                i = j;
            }
            c if c.is_ascii_whitespace() => i += 1,
            _ => {
                while i < bytes.len() && !matches!(bytes[i], b'(' | b')' | b',' | b':' | b';') {
                    i += 1;
                }
                tokens.push(NewickToken::Label);
            }
        }
    }
    tokens
}

/// Height is the longest root-to-tip path, accumulated bottom-up: a clade's depth is the deepest
/// `child depth + child branch length` among its children, which is what a phylogram's scale bar
/// measures.
fn newick_tree_stats(newick: &str) -> NewickTreeStats {
    let mut clades: Vec<f64> = vec![0.0];
    let mut depth_below = 0.0f64;
    let (mut tips, mut internals) = (0usize, 0usize);
    let mut after_close = false;
    let mut settled = true;

    let settle = |clades: &mut Vec<f64>, depth: f64, extra: f64| {
        if let Some(parent) = clades.last_mut() {
            *parent = parent.max(depth + extra);
        }
    };

    for token in tokenize_newick(newick) {
        match token {
            NewickToken::Open => {
                clades.push(0.0);
                after_close = false;
                settled = true;
            }
            NewickToken::Label => {
                // A label straight after ')' names that clade (tree files often write support values
                // there); anywhere else it is a tip.
                if !after_close {
                    tips += 1;
                    depth_below = 0.0;
                    settled = false;
                }
            }
            NewickToken::Length(len) => {
                settle(&mut clades, depth_below, len.max(0.0));
                settled = true;
                after_close = false;
            }
            NewickToken::Comma => {
                if !settled {
                    settle(&mut clades, depth_below, 0.0);
                }
                after_close = false;
                settled = true;
            }
            NewickToken::Close => {
                if !settled {
                    settle(&mut clades, depth_below, 0.0);
                }
                internals += 1;
                depth_below = clades.pop().unwrap_or(0.0);
                after_close = true;
                settled = false;
            }
        }
    }
    if !settled {
        settle(&mut clades, depth_below, 0.0);
    }
    let height = clades.first().copied().unwrap_or(depth_below).max(depth_below);
    NewickTreeStats { tips, nodes: tips + internals, height }
}

/// The tree MolBioCraft's Neighbor-Joining builder (Jukes-Cantor distances, the `build_nj_newick`
/// op) draws from the rows of an aligned sample: tip labels are the member names, as the builder
/// sanitises them (`sanitize_newick_label`).
fn reference_tree_newick(source: &SequenceDocument) -> String {
    let members = source.alignment_meta.as_ref().and_then(|m| m.sequences.as_ref());
    let (names, rows): (Vec<String>, Vec<String>) =
        members.map(|ms| ms.iter().map(|m| (m.name.clone(), m.sequence.clone())).unzip()).unwrap_or_default();
    molbiocraft_align::build_neighbor_joining_newick(&names, &rows)
}

/// The two sample tree documents, COXII and Three Kingdoms (the fictitious-character People tree
/// went with its alignment, US-01M6TGKH): each is MolBioCraft's Neighbor-Joining tree of the
/// rebuilt alignment it names (US-01M6TDSV), and carries that alignment, so the Alignment View and
/// Distances tabs open on the data the tree was built from.
fn reference_tree_documents(alignments: &[SequenceDocument]) -> Vec<SequenceDocument> {
    const TREE_BUILDER: &str = "Neighbor-Joining (Jukes-Cantor)";
    let mut trees = Vec::new();
    for (id, source_id, name, accession, organism) in [
        ("doc-tree-coxii", "doc-aln-coxii-cds", "COXII", "TREE_COXII_50", "Vertebrata"),
        ("doc-tree-three-kingdoms", "doc-aln-three-kingdoms", "Three Kingdoms", "TREE_3KINGDOMS_35", "Archaea; Bacteria; Eukaryota"),
    ] {
        let Some(source) = alignments.iter().find(|d| d.id == source_id) else { continue };
        let newick = reference_tree_newick(source);
        let stats = newick_tree_stats(&newick);
        let meta = source.alignment_meta.clone().unwrap_or_default();
        let description = format!("MolBioCraft Neighbor-Joining tree (Jukes-Cantor distances) of the {} alignment", source.name);
        let source_meta = source.doc_metadata.as_ref();
        let carried = |key: &str| source_meta.and_then(|m| m.get(key)).cloned().unwrap_or(serde_json::Value::Null);
        trees.push(SequenceDocument {
            id: id.to_string(),
            name: name.to_string(),
            accession: accession.to_string(),
            description: description.clone(),
            molecule_type: source.molecule_type,
            topology: Topology::Linear,
            sequence: source.sequence.clone(),
            features: Vec::new(),
            primers: Vec::new(),
            history: vec![HistoryTreeNode {
                id: format!("hist-{id}"),
                timestamp: REBUILT_STAMP.to_string(),
                operation: format!("Build Tree: {TREE_BUILDER}"),
                description,
                parent_ids: vec![source_id.to_string()],
                length_bp: source.sequence.len(),
                topology: Topology::Linear,
                history_color: Some("#10b981".to_string()),
                inserted_range: None,
            }],
            chromatogram: None,
            alignment_meta: Some(DocumentAlignmentMeta { tree_builder: Some(TREE_BUILDER.to_string()), ..meta }),
            document_kind: Some("tree".to_string()),
            doc_metadata: Some(make_meta(&[
                ("Newick", serde_json::json!(newick)),
                ("No. tips", serde_json::json!(stats.tips)),
                ("No. nodes", serde_json::json!(stats.nodes)),
                ("Height", serde_json::json!(format!("{:.3}", stats.height))),
                ("Tree builder", serde_json::json!(TREE_BUILDER)),
                ("Organism", serde_json::json!(organism)),
                ("# Sequences", carried("# Sequences")),
                ("% Pairwise Identity", carried("% Pairwise Identity")),
                ("% Identical Sites", carried("% Identical Sites")),
                ("Mean Coverage", carried("Mean Coverage")),
            ])),
            created_at: REBUILT_AT.to_string(),
            updated_at: REBUILT_AT.to_string(),
            folder: "Tree Documents".to_string(),
        });
    }
    trees
}

fn synthesize_sanger_chromatogram_with_quality(base_calls: &str, quality_ascii: &str) -> ChromatogramData {
    let pts_per_base = 10usize;
    let bytes = base_calls.as_bytes();
    let q_bytes = quality_ascii.as_bytes();
    let total_pts = bytes.len() * pts_per_base;
    let mut trace_a = vec![8.0f64; total_pts];
    let mut trace_c = vec![8.0f64; total_pts];
    let mut trace_g = vec![8.0f64; total_pts];
    let mut trace_t = vec![8.0f64; total_pts];
    let mut peak_locations = Vec::with_capacity(bytes.len());
    let mut phred_scores = Vec::with_capacity(bytes.len());

    for (i, &raw_b) in bytes.iter().enumerate() {
        let b = raw_b.to_ascii_uppercase();
        let center = i * pts_per_base + 5;
        peak_locations.push(center);
        let q = if i < q_bytes.len() {
            (q_bytes[i].saturating_sub(b'0')).clamp(6, 62)
        } else {
            42
        };
        phred_scores.push(q);
        let q_scale = 0.35 + (q as f64 / 62.0) * 0.75;
        let amp = ((940 - ((i % 5) * 32)) as f64) * q_scale;
        for dx in -4isize..=4isize {
            let idx_i = (center as isize) + dx;
            if idx_i >= 0 && (idx_i as usize) < total_pts {
                let idx = idx_i as usize;
                let val = (amp * (-((dx * dx) as f64) / 3.6).exp()).round();
                match b {
                    b'A' => trace_a[idx] += val,
                    b'C' => trace_c[idx] += val,
                    b'G' => trace_g[idx] += val,
                    _ => trace_t[idx] += val,
                }
            }
        }
    }

    ChromatogramData {
        trace_a,
        trace_c,
        trace_g,
        trace_t,
        peak_locations,
        phred_scores,
        base_calls: base_calls.to_ascii_uppercase(),
    }
}

/// The read simulator the contig-assembly samples are drawn with (US-01M6TDSV): every read is a
/// seeded simulation of its NCBI reference, labelled as simulated, never a read from another
/// program's sample set. src/__tests__/sampleAssemblyReads.test.ts re-implements it, regenerates
/// each read set from the seed its document stores and the reference scripts/outside-data/fetch.sh
/// fetches, and gets the stored reads exactly.
///
/// The generator is mulberry32 (32-bit state, one `next` per draw); `below(n)` is `next() % n`.
struct ReadSimRng(u32);

impl ReadSimRng {
    fn next(&mut self) -> u32 {
        self.0 = self.0.wrapping_add(0x6D2B_79F5);
        let mut t = self.0;
        t = (t ^ (t >> 15)).wrapping_mul(t | 1);
        t ^= t.wrapping_add((t ^ (t >> 7)).wrapping_mul(t | 61));
        t ^ (t >> 14)
    }
    fn below(&mut self, n: u32) -> u32 {
        self.next() % n
    }
}

/// A sequencing error: one draw picks one of the three other bases, in `ACGT` order. A base other
/// than A, C, G or T is kept (the draw is still made).
fn sim_substitute(base: u8, rng: &mut ReadSimRng) -> u8 {
    let pick = rng.below(3) as usize;
    let others: Vec<u8> = b"ACGT".iter().copied().filter(|&b| b != base).collect();
    if others.len() == 3 {
        others[pick]
    } else {
        base
    }
}

/// The reference strand a read is drawn from: `template[start..start + len]`, reverse-complemented
/// for a reverse read, upper case.
fn sim_template(reference: &str, start: usize, len: usize, reverse: bool) -> Vec<u8> {
    let slice = &reference[start..start + len];
    let s = if reverse { reverse_complement_iupac(slice, false) } else { slice.to_string() };
    s.to_ascii_uppercase().into_bytes()
}

/// Expected Sanger base quality at read position `i` of `len`: rising over the first 30 bases,
/// flat at 58, and falling over the last 90.
fn sanger_quality_profile(i: usize, len: usize) -> i64 {
    if i < 30 {
        12 + (i as i64 * 46) / 30
    } else if i + 90 >= len {
        58 - (((i + 90 - len) as i64) * 48) / 90
    } else {
        58
    }
}

/// Per-mille error rate of a base called at quality `q`.
fn sanger_error_per_mille(q: i64) -> u32 {
    match q {
        q if q < 10 => 250,
        q if q < 20 => 60,
        q if q < 30 => 8,
        _ => 1,
    }
}

/// A simulated Sanger read of `reference[start..start + len]` (reverse-complemented when
/// `reverse`): per base, in read order, the quality is the profile plus `below(9) - 4`, clamped to
/// 6..=60; then `below(1000) < error_per_mille(q)` makes the base an error ([`sim_substitute`]).
/// Returns the base calls and their Phred qualities.
fn simulate_sanger_read(reference: &str, start: usize, len: usize, reverse: bool, seed: u32) -> (String, Vec<u8>) {
    let mut rng = ReadSimRng(seed);
    let template = sim_template(reference, start, len, reverse);
    let mut calls = Vec::with_capacity(len);
    let mut quals = Vec::with_capacity(len);
    for (i, &b) in template.iter().enumerate() {
        let q = (sanger_quality_profile(i, len) + rng.below(9) as i64 - 4).clamp(6, 60);
        let call = if rng.below(1000) < sanger_error_per_mille(q) { sim_substitute(b, &mut rng) } else { b };
        calls.push(call);
        quals.push(q as u8);
    }
    (String::from_utf8_lossy(&calls).into_owned(), quals)
}

/// Applies a flat per-mille substitution rate to a read, base by base.
fn sim_with_errors(template: Vec<u8>, per_mille: u32, rng: &mut ReadSimRng) -> String {
    let out: Vec<u8> =
        template.into_iter().map(|b| if rng.below(1000) < per_mille { sim_substitute(b, rng) } else { b }).collect();
    String::from_utf8_lossy(&out).into_owned()
}

/// `count` simulated Ion Torrent-length single-end reads: per read, its length is
/// `196 + below(33)`, its start `below(reference length - length + 1)`, its strand reverse when
/// `below(2) == 1`, then 5 per mille substitutions in read order. Returns (start, length, reverse,
/// read) per read.
fn simulate_ion_torrent_reads(reference: &str, count: usize, seed: u32) -> Vec<(usize, usize, bool, String)> {
    let mut rng = ReadSimRng(seed);
    (0..count)
        .map(|_| {
            let len = 196 + rng.below(33) as usize;
            let start = rng.below((reference.len() - len + 1) as u32) as usize;
            let reverse = rng.below(2) == 1;
            let read = sim_with_errors(sim_template(reference, start, len, reverse), 5, &mut rng);
            (start, len, reverse, read)
        })
        .collect()
}

/// `pairs` simulated 90 bp Illumina paired-end (FR) read pairs: per pair, the insert is
/// `250 + below(101)` bp, its start `below(reference length - insert + 1)`; read 1 is the insert's
/// first 90 bases, read 2 the reverse complement of its last 90, each then given 2 per mille
/// substitutions in read order. Returns (start, insert, read 1, read 2) per pair.
fn simulate_illumina_pairs(reference: &str, pairs: usize, seed: u32) -> Vec<(usize, usize, String, String)> {
    let mut rng = ReadSimRng(seed);
    (0..pairs)
        .map(|_| {
            let insert = 250 + rng.below(101) as usize;
            let start = rng.below((reference.len() - insert + 1) as u32) as usize;
            let r1 = sim_with_errors(sim_template(reference, start, 90, false), 2, &mut rng);
            let r2 = sim_with_errors(sim_template(reference, start + insert - 90, 90, true), 2, &mut rng);
            (start, insert, r1, r2)
        })
        .collect()
}

/// The COI reference the Sanger reads are drawn from: NC_001709.1 (Drosophila melanogaster
/// mitochondrion) 1,474 -> 2,233, the 5' 760 bp of the COX1 coding sequence (CDS 1,474..3,009).
const COI_REFERENCE_RECORD: &str = "NC_001709.1";
const COI_REFERENCE_START: usize = 1474;
const COI_REFERENCE: &str = concat!(
    "TCGCGACAATGATTATTTTCTACAAATCATAAAGATATTGGAACTTTATATTTTATTTTTGGAGCTTGAGCTGGAATAGT",
    "TGGAACATCTTTAAGAATTTTAATTCGAGCTGAATTAGGACATCCTGGAGCATTAATTGGAGATGATCAAATTTATAATG",
    "TAATTGTAACTGCACATGCTTTTATTATAATTTTTTTTATGGTTATACCTATTATAATTGGTGGATTTGGAAATTGATTA",
    "GTGCCTTTAATATTAGGTGCTCCTGATATAGCATTCCCACGAATAAATAATATAAGATTTTGACTACTACCTCCTGCTCT",
    "TTCTTTACTATTAGTAAGTAGAATAGTTGAAAATGGAGCTGGAACAGGATGAACTGTTTATCCACCTTTATCCGCTGGAA",
    "TTGCTCATGGTGGAGCTTCAGTTGATTTAGCTATTTTTTCTCTACATTTAGCAGGGATTTCTTCAATTTTAGGAGCTGTA",
    "AATTTTATTACAACTGTAATTAATATACGATCAACAGGAATTTCATTAGATCGTATACCTTTATTTGTTTGATCAGTAGT",
    "TATTACTGCTTTATTATTATTATTATCACTTCCAGTACTAGCAGGAGCTATTACTATATTATTAACAGATCGAAATTTAA",
    "ATACATCATTTTTTGACCCAGCGGGAGGAGGAGATCCTATTTTATATCAACATTTATTTTGATTTTTTGGTCACCCTGAA",
    "GTTTATATTTTAATTTTACCTGGATTTGGAATAATTTCTC",
);
/// The two COI Sanger reads: (document id, name, start in the reference region, length, reverse, seed).
const COI_READS: [(&str, &str, usize, usize, bool, u32); 2] = [
    ("doc-contig-coi-fwd", "COI fwd read", 0, 724, false, 20_261_108),
    ("doc-contig-coi-rev", "COI rev read", 39, 721, true, 20_261_109),
];
/// The yghJ read sets: the reference is the E. coli K-12 MG1655 yghJ CDS (YP_026189.1).
const YGHJ_REFERENCE_RECORD: &str = "YP_026189.1";
const YGHJ_ION_SEED: u32 = 20_261_110;
const YGHJ_ION_READS: usize = 24;
const YGHJ_ILLUMINA_SEED: u32 = 20_261_111;
const YGHJ_ILLUMINA_PAIRS: usize = 12;
const SIM_ORGANISM_YGHJ: &str = "Escherichia coli str. K-12 substr. MG1655";

/// One simulated COI Sanger read document, with its trace drawn from its simulated qualities.
fn coi_read_document(index: usize) -> SequenceDocument {
    let (id, name, start, len, reverse, seed) = COI_READS[index];
    let (calls, quals) = simulate_sanger_read(COI_REFERENCE, start, len, reverse, seed);
    let quality_ascii: String = quals.iter().map(|&q| (q + b'0') as char).collect();
    let (from, to) = (COI_REFERENCE_START + start, COI_REFERENCE_START + start + len - 1);
    let strand_word = if reverse { "reverse" } else { "forward" };
    let region = format!("{} -> {}", molbiocraft_core::format_thousands(from), molbiocraft_core::format_thousands(to));
    let description = format!(
        "Simulated {strand_word} Sanger read of the Drosophila melanogaster COX1 gene ({COI_REFERENCE_RECORD} {region}), seed {seed}"
    );
    SequenceDocument {
        id: id.to_string(),
        name: name.to_string(),
        accession: format!("SIM_{}", id.trim_start_matches("doc-contig-").replace('-', "_").to_ascii_uppercase()),
        description: description.clone(),
        molecule_type: MoleculeType::DNA,
        topology: Topology::Linear,
        sequence: calls.clone(),
        features: Vec::new(),
        primers: Vec::new(),
        history: vec![HistoryTreeNode {
            id: format!("hist-{id}"),
            timestamp: REBUILT_STAMP.to_string(),
            operation: "Simulate Sanger Read".to_string(),
            description,
            parent_ids: Vec::new(),
            length_bp: len,
            topology: Topology::Linear,
            history_color: None,
            inserted_range: None,
        }],
        chromatogram: Some(synthesize_sanger_chromatogram_with_quality(&calls, &quality_ascii)),
        alignment_meta: None,
        document_kind: Some("trace".to_string()),
        doc_metadata: Some(make_meta(&[
            ("Organism", serde_json::json!("Drosophila melanogaster")),
            ("Sequence Length", serde_json::json!(molbiocraft_core::format_thousands(len))),
            ("Is Forward Read", serde_json::json!(if reverse { "false" } else { "true" })),
            ("Molecule Type", serde_json::json!("DNA")),
            ("Read Technology", serde_json::json!("Sanger (simulated)")),
            ("Topology", serde_json::json!("linear")),
            ("Simulated", serde_json::json!("yes")),
            ("Simulation reference", serde_json::json!(COI_REFERENCE_RECORD)),
            ("Simulation region", serde_json::json!(region)),
            ("Simulation strand", serde_json::json!(if reverse { -1 } else { 1 })),
            ("Simulation seed", serde_json::json!(seed)),
            ("Simulation model", serde_json::json!("sanger")),
        ])),
        created_at: REBUILT_AT.to_string(),
        updated_at: REBUILT_AT.to_string(),
        folder: "Contig Assembly".to_string(),
    }
}

/// The COI contig: MolBioCraft's Sanger contig assembler (partial-order alignment, with its
/// quality pre-trim) run on the two simulated reads.
fn coi_assembly_document(reads: &[SequenceDocument]) -> SequenceDocument {
    let inputs: Vec<PoaReadInput> = reads
        .iter()
        .map(|r| PoaReadInput {
            id: r.id.clone(),
            name: r.name.clone(),
            sequence: r.sequence.clone(),
            phred_scores: r.chromatogram.as_ref().map(|c| c.phred_scores.clone()).unwrap_or_default(),
        })
        .collect();
    let report = assemble_sanger_contig_poa(&inputs, "COI Assembly", true);
    let members: Vec<AlignmentMemberSequence> = report
        .aligned_reads
        .iter()
        .map(|row| AlignmentMemberSequence {
            id: row.id.clone(),
            name: row.name.clone(),
            accession: None,
            description: reads.iter().find(|r| r.id == row.id).map(|r| r.description.clone()),
            organism: Some("Drosophila melanogaster".to_string()),
            sequence: row.aligned_row.clone(),
            strand: Some(row.strand),
            features: Vec::new(),
        })
        .collect();
    let mut doc = report.contig_document;
    let width = doc.sequence.len();
    let n = members.len();
    let residues: usize = members.iter().map(|m| m.sequence.bytes().filter(|&b| b != b'-').count()).sum();
    let mut meta = doc.doc_metadata.take().unwrap_or_default();
    for (k, v) in [
        ("Organism", serde_json::json!("Drosophila melanogaster")),
        ("Sequence Length", serde_json::json!(molbiocraft_core::format_thousands(width))),
        ("# Sequences", serde_json::json!(n)),
        ("# Nucleotides", serde_json::json!(molbiocraft_core::format_thousands(residues))),
        ("Molecule Type", serde_json::json!("DNA")),
        ("Read Technology", serde_json::json!("Sanger (simulated)")),
        ("Simulated", serde_json::json!("yes")),
        ("Trim Parameters", serde_json::json!("Error probability: 0.05")),
    ] {
        meta.insert(k.to_string(), v);
    }
    if let Some(m) = doc.alignment_meta.as_mut() {
        m.sequences = Some(members);
        m.genetic_code_label = None;
    }
    doc.id = "doc-contig-coi-assembly".to_string();
    doc.name = "COI Assembly".to_string();
    doc.accession = "SIM_COI_CONTIG".to_string();
    doc.description = format!(
        "MolBioCraft contig of the 2 simulated COI Sanger reads (COI fwd read, COI rev read), {width} bp"
    );
    for h in doc.history.iter_mut() {
        h.id = "hist-coi-assembly".to_string();
        h.timestamp = REBUILT_STAMP.to_string();
    }
    doc.doc_metadata = Some(meta);
    doc.created_at = REBUILT_AT.to_string();
    doc.updated_at = REBUILT_AT.to_string();
    doc.folder = "Contig Assembly".to_string();
    doc
}

/// A simulated read-set document (yghJ Ion Torrent or Illumina): unaligned reads, no traces.
#[allow(clippy::too_many_arguments)]
fn simulated_read_set_document(
    id: &str,
    name: &str,
    description: String,
    technology: &str,
    model: &str,
    seed: u32,
    members: Vec<AlignmentMemberSequence>,
    extra: &[(&str, serde_json::Value)],
) -> SequenceDocument {
    let n = members.len();
    let lengths: Vec<usize> = members.iter().map(|m| m.sequence.len()).collect();
    let residues: usize = lengths.iter().sum();
    let gc: usize = members.iter().map(|m| m.sequence.bytes().filter(|b| matches!(b, b'G' | b'C')).count()).sum();
    let mut entries = vec![
        ("Organism", serde_json::json!(SIM_ORGANISM_YGHJ)),
        ("Sequence Length", serde_json::json!("-")),
        ("# Sequences", serde_json::json!(molbiocraft_core::format_thousands(n))),
        ("# Nucleotides", serde_json::json!(molbiocraft_core::format_thousands(residues))),
        ("% GC", serde_json::json!(format!("{:.1}%", 100.0 * gc as f64 / residues.max(1) as f64))),
        ("Max Sequence Length", serde_json::json!(lengths.iter().copied().max().unwrap_or(0).to_string())),
        ("Min Sequence Length", serde_json::json!(lengths.iter().copied().min().unwrap_or(0).to_string())),
        ("Molecule Type", serde_json::json!("DNA")),
        ("Read Technology", serde_json::json!(format!("{technology} (simulated)"))),
        ("Simulated", serde_json::json!("yes")),
        ("Simulation reference", serde_json::json!(YGHJ_REFERENCE_RECORD)),
        ("Simulation seed", serde_json::json!(seed)),
        ("Simulation model", serde_json::json!(model)),
    ];
    entries.extend(extra.iter().cloned());
    SequenceDocument {
        id: id.to_string(),
        name: name.to_string(),
        accession: format!("SIM_{}", id.trim_start_matches("doc-contig-").replace('-', "_").to_ascii_uppercase()),
        description: description.clone(),
        molecule_type: MoleculeType::DNA,
        topology: Topology::Linear,
        sequence: members.first().map(|m| m.sequence.clone()).unwrap_or_default(),
        features: Vec::new(),
        primers: Vec::new(),
        history: vec![HistoryTreeNode {
            id: format!("hist-{id}"),
            timestamp: REBUILT_STAMP.to_string(),
            operation: format!("Simulate {technology} Reads"),
            description,
            parent_ids: Vec::new(),
            length_bp: lengths.first().copied().unwrap_or(0),
            topology: Topology::Linear,
            history_color: None,
            inserted_range: None,
        }],
        chromatogram: None,
        alignment_meta: Some(DocumentAlignmentMeta {
            sequence_count: Some(n),
            pairwise_identity_pct: None,
            identical_sites_pct: None,
            genetic_code_label: None,
            mean_coverage_x: None,
            tree_builder: None,
            is_aligned: Some(false),
            sequences: Some(members),
        }),
        document_kind: Some("contig".to_string()),
        doc_metadata: Some(make_meta(&entries)),
        created_at: REBUILT_AT.to_string(),
        updated_at: REBUILT_AT.to_string(),
        folder: "Contig Assembly".to_string(),
    }
}

fn yghj_ion_torrent_document(reference: &str) -> SequenceDocument {
    let members = simulate_ion_torrent_reads(reference, YGHJ_ION_READS, YGHJ_ION_SEED)
        .into_iter()
        .enumerate()
        .map(|(idx, (start, len, reverse, read))| AlignmentMemberSequence {
            id: format!("ion-read-{}", idx + 1),
            name: format!("yghJ_ion_sim_{:02}", idx + 1),
            accession: None,
            description: Some(format!(
                "Simulated Ion Torrent-length read of the yghJ CDS ({YGHJ_REFERENCE_RECORD} {}..{}, {} strand)",
                start + 1,
                start + len,
                if reverse { "reverse" } else { "forward" }
            )),
            organism: Some(SIM_ORGANISM_YGHJ.to_string()),
            sequence: read,
            strand: Some(if reverse { -1 } else { 1 }),
            features: Vec::new(),
        })
        .collect();
    simulated_read_set_document(
        "doc-contig-yghj-ion-torrent",
        "yghJ Ion Torrent reads",
        format!(
            "{YGHJ_ION_READS} simulated Ion Torrent-length single-end reads of the E. coli K-12 MG1655 yghJ CDS ({YGHJ_REFERENCE_RECORD}), seed {YGHJ_ION_SEED}"
        ),
        "Ion Torrent",
        "ion-torrent",
        YGHJ_ION_SEED,
        members,
        &[],
    )
}

fn yghj_illumina_document(reference: &str) -> SequenceDocument {
    let mut members = Vec::with_capacity(YGHJ_ILLUMINA_PAIRS * 2);
    for (idx, (start, insert, r1, r2)) in simulate_illumina_pairs(reference, YGHJ_ILLUMINA_PAIRS, YGHJ_ILLUMINA_SEED).into_iter().enumerate() {
        let pair = idx + 1;
        members.push(AlignmentMemberSequence {
            id: format!("illumina-pair-{pair}-1"),
            name: format!("yghJ_ill_sim_{pair:02}/1"),
            accession: None,
            description: Some(format!(
                "Simulated 90 bp paired-end read 1 (forward, {YGHJ_REFERENCE_RECORD} {}..{}; {insert} bp insert)",
                start + 1,
                start + 90
            )),
            organism: Some(SIM_ORGANISM_YGHJ.to_string()),
            sequence: r1,
            strand: Some(1),
            features: Vec::new(),
        });
        members.push(AlignmentMemberSequence {
            id: format!("illumina-pair-{pair}-2"),
            name: format!("yghJ_ill_sim_{pair:02}/2"),
            accession: None,
            // Paired-end mates face each other (FR): read 2 is the reverse complement of the insert's end.
            description: Some(format!(
                "Simulated 90 bp paired-end read 2 (reverse complement of {YGHJ_REFERENCE_RECORD} {}..{})",
                start + insert - 89,
                start + insert
            )),
            organism: Some(SIM_ORGANISM_YGHJ.to_string()),
            sequence: r2,
            strand: Some(-1),
            features: Vec::new(),
        });
    }
    simulated_read_set_document(
        "doc-contig-yghj-illumina",
        "yghJ paired Illumina reads",
        format!(
            "{} simulated 90 bp Illumina paired-end reads ({YGHJ_ILLUMINA_PAIRS} FR pairs) of the E. coli K-12 MG1655 yghJ CDS ({YGHJ_REFERENCE_RECORD}), seed {YGHJ_ILLUMINA_SEED}",
            YGHJ_ILLUMINA_PAIRS * 2
        ),
        "Illumina",
        "illumina-paired",
        YGHJ_ILLUMINA_SEED,
        members,
        &[("Paired Data Type", serde_json::json!("Paired End"))],
    )
}

