#[cfg(test)]
mod tree_tests {
    use super::*;

    /// The parser was pinned during development against a reference record that publishes its
    /// own tree shape (20 tips, 38 nodes, height 0.28077256532523004); this fixture reproduces
    /// that arithmetic on a topology of the same shape, two nested clades deep.
    #[test]
    fn newick_stats_count_tips_nodes_and_longest_root_to_tip_path() {
        let stats = newick_tree_stats("((A:0.1,B:0.2):0.05,(C:0.3,(D:0.4,E:0.05):0.1):0.02);");
        assert_eq!(stats.tips, 5);
        // 5 tips + 4 internal nodes (three clades plus the root).
        assert_eq!(stats.nodes, 9);
        // Deepest path is root -> clade(0.02) -> clade(0.1) -> D(0.4) = 0.52.
        assert!((stats.height - 0.52).abs() < 1e-9, "height was {}", stats.height);
    }

    #[test]
    fn newick_stats_handle_quoted_labels_support_values_and_nesting() {
        // ((A:1,B:2)95:3,C:10); — deepest path is C at 10, and the support label 95 is not a tip.
        let stats = newick_tree_stats("(('A a':1,B:2)95:3,C:10);");
        assert_eq!(stats.tips, 3);
        assert_eq!(stats.nodes, 5);
        assert!((stats.height - 10.0).abs() < 1e-9, "height was {}", stats.height);
        // Through the nested clade the path is 2 + 3 = 5, so the longer C branch must win.
        let shallow = newick_tree_stats("(('A a':1,B:2)95:3,C:4);");
        assert!((shallow.height - 5.0).abs() < 1e-9, "height was {}", shallow.height);
    }

    /// US-01M6TDSV AC4: each tree document is MolBioCraft's Neighbor-Joining tree (the
    /// `build_nj_newick` op: Jukes-Cantor distances) of a rebuilt alignment, and carries that
    /// alignment. A tree copied from another program, or built from other rows, has another Newick
    /// string and fails; so does a tree that drops or reorders the alignment it names.
    #[test]
    fn reference_trees_carry_the_alignment_they_were_built_from() {
        let docs = get_alignment_sample_documents();
        assert!(!docs.iter().any(|d| d.name == "People"), "the fictitious-character People alignment and tree are dropped");
        let trees: Vec<&SequenceDocument> = docs.iter().filter(|d| d.folder == "Tree Documents").collect();
        let names: Vec<&str> = trees.iter().map(|d| d.name.as_str()).collect();
        assert_eq!(names, ["COXII", "Three Kingdoms"], "the two tree documents (D0094)");
        for (tree, tips) in trees.iter().zip([50usize, 35]) {
            let name = &tree.name;
            let parents: Vec<&String> = tree.history.iter().flat_map(|h| h.parent_ids.iter()).collect();
            assert_eq!(parents.len(), 1, "{name} names the one alignment it was built from");
            let source = docs.iter().find(|d| &d.id == parents[0] && d.folder == "Alignments")
                .unwrap_or_else(|| panic!("{name}: its alignment {} ships", parents[0]));
            let src_meta = source.doc_metadata.as_ref().expect("the alignment carries metadata");
            let method = src_meta["Alignment method"].as_str().unwrap_or_default();
            assert!(["MolBioCraft MSA", "MolBioCraft Translation Alignment"].contains(&method), "{name} is built from a rebuilt alignment, not {method:?}");
            let src_members = source.alignment_meta.as_ref().and_then(|m| m.sequences.as_ref()).expect("alignment members");
            assert_eq!(source.alignment_meta.as_ref().and_then(|m| m.is_aligned), Some(true), "{name}: its source is aligned");

            let aln = tree.alignment_meta.as_ref().expect("tree carries its alignment");
            let seqs = aln.sequences.as_ref().expect("alignment members travel with the tree");
            let rows = |ms: &[AlignmentMemberSequence]| ms.iter().map(|m| (m.id.clone(), m.name.clone(), m.sequence.clone())).collect::<Vec<_>>();
            assert_eq!(rows(seqs), rows(src_members), "{name} carries its alignment's rows, in order");
            assert_eq!(seqs.len(), tips, "{name} alignment members");

            // The stored topology is the NJ tree of those rows, exactly.
            let meta = tree.doc_metadata.as_ref().expect("tree carries metadata");
            let newick = meta["Newick"].as_str().expect("tree stores a Newick string");
            let tip_names: Vec<String> = src_members.iter().map(|m| m.name.clone()).collect();
            let tip_rows: Vec<String> = src_members.iter().map(|m| m.sequence.clone()).collect();
            assert_eq!(newick, molbiocraft_align::build_neighbor_joining_newick(&tip_names, &tip_rows), "{name} is MolBioCraft's NJ tree of its alignment");
            assert_eq!(meta["Tree builder"], serde_json::json!("Neighbor-Joining (Jukes-Cantor)"), "{name} tree builder");
            assert_eq!(aln.tree_builder.as_deref(), Some("Neighbor-Joining (Jukes-Cantor)"), "{name} tree builder");
            assert_eq!(meta["No. tips"], serde_json::json!(tips), "{name} tip count");
            for m in src_members {
                let label = molbiocraft_align::sanitize_newick_label(&m.name);
                assert!(newick.contains(&format!("({label}:")) || newick.contains(&format!(",{label}:")), "{name}: tip {label:?} in the topology");
            }
            // The tree is MolBioCraft's document, not another program's.
            assert!(!meta.contains_key("Created") && !meta.contains_key("Modified") && !meta.contains_key("Source Format"), "{name} keeps no foreign document field");
            assert!(tree.created_at.as_str() >= "2026-10-01" && tree.updated_at.as_str() >= "2026-10-01", "{name} dates");
        }
    }
}
